import { Controller, Patch, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr00603Controller {
  @Patch('/partners/:partnerId')
  async updatePartner2(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const partnerId = req.params['partnerId'];
    if (!/^\d{1,18}$/.test(partnerId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '거래처 ID 형식이 올바르지 않습니다.');
    }
    const partnerName = data['partnerName'];
    const businessRegNo = data['businessRegNo'];
    const representativeName = data['representativeName'];
    if (partnerName !== undefined && partnerName !== null) {
      if (typeof partnerName !== 'string' || partnerName.trim() === '' || partnerName.length > 200) {
        throw new ApiError(400, 'VALIDATION_FAILED', '거래처 명칭은 200자 이내의 글자로 입력해 주세요.');
      }
    }
    if (businessRegNo !== undefined && businessRegNo !== null) {
      if (typeof businessRegNo !== 'string' || !/^\d{1,10}$/.test(businessRegNo)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '사업자등록번호는 10자리 이내의 숫자로 입력해 주세요.');
      }
    }
    if (representativeName !== undefined && representativeName !== null) {
      if (typeof representativeName !== 'string' || representativeName.length > 100) {
        throw new ApiError(400, 'VALIDATION_FAILED', '대표자명은 100자 이내의 글자로 입력해 주세요.');
      }
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT partner_id AS "partnerId" FROM partner WHERE partner_id = CAST(:partnerId AS bigint)',
        { partnerId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PARTNER_NOT_FOUND', '거래처가 존재하지 않습니다.');
      }
      if (typeof businessRegNo === 'string' && businessRegNo !== '') {
        const dup = await db.query(
          'SELECT partner_id AS "partnerId" FROM partner WHERE business_reg_no = :businessRegNo AND partner_id <> CAST(:partnerId AS bigint)',
          { businessRegNo, partnerId },
        );
        if (dup.length > 0) {
          throw new ApiError(409, 'PARTNER_DUPLICATED', '이미 등록된 사업자등록번호입니다.');
        }
      }
      const rows = await db.query(
        `UPDATE partner
            SET partner_name = COALESCE(:partnerName, partner_name),
                business_reg_no = COALESCE(:businessRegNo, business_reg_no),
                representative_name = COALESCE(:representativeName, representative_name),
                updated_at = now()
          WHERE partner_id = CAST(:partnerId AS bigint)
          RETURNING partner_id AS "partnerId"`,
        {
          partnerId,
          partnerName: partnerName ?? null,
          businessRegNo: businessRegNo ?? null,
          representativeName: representativeName ?? null,
        },
      );
      return { partnerId: Number(rows[0].partnerId) };
    });
  }
}

