import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Filters,
  Form,
  Pager,
  Select,
  TextInput,
  Tiles,
  call,
  useData,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;
const TYPES: [string, string][] = [
  ['일반', '일반'],
  ['금융', '금융'],
];

export default function FnSfr00603Page({ role, notify }: PageProps) {
  const [name, setName] = useState('');
  const [type, setType] = useState('');
  const [applied, setApplied] = useState({ name: '', type: '' });
  const [page, setPage] = useState(0);
  const [editing, setEditing] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);

  const list = useData<Page>(
    () =>
      call<Page>('GET', '/partners', role, undefined, {
        partnerName: applied.name,
        partnerType: applied.type,
        page,
        size: SIZE,
      }),
    [applied, page, role],
  );
  const rows = list.data?.items ?? [];
  const total = list.data?.total ?? 0;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>거래처 수</h2>
        <Tiles items={[['조회된 거래처', total]]} />
      </section>
      <section className="box span-8">
        <h2>거래처 목록</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied({ name, type });
          }}
          onReset={() => {
            setName('');
            setType('');
            setPage(0);
            setApplied({ name: '', type: '' });
          }}
        >
          <Field label="거래처 명칭">
            <TextInput value={name} onChange={setName} />
          </Field>
          <Field label="거래처 유형">
            <Select value={type} onChange={setType} options={TYPES} />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={() => setCreating(true)}>
            거래처 등록
          </button>
        </Band>
        {list.error ? <p>{list.error}</p> : null}
        <DataTable
          rows={rows}
          empty="거래처가 없습니다."
          columns={[
            { key: 'partnerCode', label: '거래처 코드' },
            { key: 'partnerName', label: '거래처 명칭' },
            { key: 'partnerType', label: '거래처 유형', render: (r) => <Badge value={r.partnerType} /> },
            { key: 'businessRegNo', label: '사업자등록번호' },
            { key: 'representativeName', label: '대표자명' },
            {
              key: 'action',
              label: '수정',
              render: (r) => (
                <button type="button" onClick={() => setEditing(r)}>
                  수정
                </button>
              ),
            },
          ]}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {editing ? (
        <EditDrawer
          row={editing}
          role={role}
          onClose={() => setEditing(null)}
          onDone={() => {
            setEditing(null);
            notify('거래처를 수정했습니다.');
            list.reload();
          }}
        />
      ) : null}
      {creating ? (
        <CreateDrawer
          role={role}
          onClose={() => setCreating(false)}
          onDone={() => {
            setCreating(false);
            notify('거래처를 등록했습니다.');
            list.reload();
          }}
        />
      ) : null}
    </div>
  );
}

function EditDrawer({ row, role, onClose, onDone }: { row: Row; role: string; onClose: () => void; onDone: () => void }) {
  const [partnerName, setPartnerName] = useState(String(row.partnerName ?? ''));
  const [businessRegNo, setBusinessRegNo] = useState(String(row.businessRegNo ?? ''));
  const [representativeName, setRepresentativeName] = useState(String(row.representativeName ?? ''));
  return (
    <Drawer title="거래처 수정" onClose={onClose}>
      <Form
        submit="저장"
        onSubmit={async () => {
          if (partnerName.trim() === '') {
            throw new Error('거래처 명칭을 입력해 주세요.');
          }
          const body: Row = { partnerName, representativeName };
          if (businessRegNo !== '') {
            body.businessRegNo = businessRegNo;
          }
          await call('PATCH', `/partners/${row.partnerId}`, role, body);
          onDone();
        }}
      >
        <Field label="거래처 명칭" required>
          <TextInput value={partnerName} onChange={setPartnerName} />
        </Field>
        <Field label="사업자등록번호">
          <TextInput value={businessRegNo} onChange={setBusinessRegNo} />
        </Field>
        <Field label="대표자명">
          <TextInput value={representativeName} onChange={setRepresentativeName} />
        </Field>
      </Form>
    </Drawer>
  );
}

function CreateDrawer({ role, onClose, onDone }: { role: string; onClose: () => void; onDone: () => void }) {
  const [partnerType, setPartnerType] = useState('');
  const [partnerName, setPartnerName] = useState('');
  const [partnerCode, setPartnerCode] = useState('');
  const [businessRegNo, setBusinessRegNo] = useState('');
  const [representativeName, setRepresentativeName] = useState('');
  const [taxInvoiceYn, setTaxInvoiceYn] = useState('');
  return (
    <Drawer title="거래처 등록" onClose={onClose}>
      <Form
        submit="등록"
        onSubmit={async () => {
          if (!partnerType || !partnerName.trim() || !partnerCode.trim() || !taxInvoiceYn) {
            throw new Error('필수 항목을 모두 입력해 주세요.');
          }
          const body: Row = {
            partnerType,
            partnerName,
            partnerCode,
            taxInvoiceYn: taxInvoiceYn === 'Y',
          };
          if (businessRegNo !== '') {
            body.businessRegNo = businessRegNo;
          }
          if (representativeName !== '') {
            body.representativeName = representativeName;
          }
          await call('POST', '/partners', role, body);
          onDone();
        }}
      >
        <Field label="거래처 유형" required>
          <Select value={partnerType} onChange={setPartnerType} options={TYPES} />
        </Field>
        <Field label="거래처 코드" required>
          <TextInput value={partnerCode} onChange={setPartnerCode} />
        </Field>
        <Field label="거래처 명칭" required>
          <TextInput value={partnerName} onChange={setPartnerName} />
        </Field>
        <Field label="사업자등록번호">
          <TextInput value={businessRegNo} onChange={setBusinessRegNo} />
        </Field>
        <Field label="대표자명">
          <TextInput value={representativeName} onChange={setRepresentativeName} />
        </Field>
        <Field label="세금계산서 여부" required>
          <Select
            value={taxInvoiceYn}
            onChange={setTaxInvoiceYn}
            options={[
              ['Y', '예'],
              ['N', '아니오'],
            ]}
          />
        </Field>
      </Form>
    </Drawer>
  );
}
